#!/usr/bin/env node
// Generates an editor-agnostic .http request collection (VS Code REST Client /
// JetBrains HTTP Client / httpyac) from the OpenAPI contract, grouped by tag,
// plus a multi-environment http-client.env.json (see scripts/lib/http-collection.mjs).
// Regenerated by `task gen`; never edit the output by hand.
import { readFileSync, writeFileSync, mkdirSync, readdirSync, unlinkSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { parse } from "yaml";
import { generateCollection } from "./lib/http-collection.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = parse(readFileSync(join(root, "api/openapi.yaml"), "utf8"));
const outDir = join(root, "collections");
mkdirSync(outDir, { recursive: true });

// A renamed or removed tag must not leave its old .http file behind (the drift
// gate only sees what is written, not what should be gone). Remove every file
// this generator owns — the generated .http files and the env file — and keep
// the git-ignored private env file with the developer's tokens.
for (const name of readdirSync(outDir)) {
  const path = join(outDir, name);
  const generatedHttp =
    name.endsWith(".http") &&
    readFileSync(path, "utf8").includes("generated from api/openapi.yaml by task gen");
  if (generatedHttp || name === "http-client.env.json") unlinkSync(path);
}

const { files, env } = generateCollection(spec);
for (const [name, content] of files) writeFileSync(join(outDir, name), content);
writeFileSync(join(outDir, "http-client.env.json"), JSON.stringify(env, null, 2) + "\n");

console.log(`Generated ${files.size} .http file(s) + http-client.env.json in collections/`);
